		bool ok = 1;

		for(int I = 0;I < solve.size();++I){

			if(solve[I] == '@'){
				if(ok){
					cout << '@';
					ok = false;
				}
				else{
					cout << "at";
				}
				continue;
			}
			cout << solve[I];
		}
